import json
from typing import Any, Dict

def _offers_of(obj):
    # V3.12 多商品：优先取 offers[] 数组；旧单品平面对象包装为 1 品（offer_seq=1）
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    req_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
                req_id = str(first.get('req_id') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
            req_id = str(arr.get('req_id') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    offers = []
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            if not req_id:
                req_id = str(inner.get('req_id') or '')
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
    except Exception:
        offers = []
    ret: Output = {
        "record_json": record_json,
        "req_id": req_id,
        "offer_id": offer_id,
        "offers": json.dumps(offers, ensure_ascii=False)
    }
    return ret

import json

def _roster_map(raw):
    # 权威名册归一：入参可为 [{offer_seq,name,quantity}] / {offers:[...]} / JSON 字符串
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        obj = obj.get('offers')
    if not isinstance(obj, list):
        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

_STATUS_CN = {'SUCCESS': '已发起', 'PENDING': '处理中', 'PARTIAL': '部分成功', 'FAIL': '失败', 'FAILED': '失败'}
_SCENE_STATUS_CN = {'SUCCESS': '通过', 'PASS': '通过', 'FAIL': '失败', 'FAILED': '失败',
                    'PENDING': '处理中', 'RUNNING': '执行中', 'WAIT': '待执行'}

def _as_list(v):
    if isinstance(v, list):
        return v
    if isinstance(v, str):
        s = v.strip()
        if s[:1] in '[{':
            try:
                return json.loads(s)
            except Exception:
                return []
    return []

def _scene_line(scene, idx):
    if not isinstance(scene, dict):
        return '    ' + str(idx) + '. ' + str(scene) + ' · 待执行'
    nbr = str(scene.get('testSceneNbr') or scene.get('sceneNbr') or scene.get('code') or '?')
    name = str(scene.get('testSceneName') or scene.get('sceneName') or scene.get('name') or '未命名场景')
    raw = str(scene.get('status') or scene.get('result') or 'WAIT').upper()
    st = _SCENE_STATUS_CN.get(raw, '待执行')
    return '    ' + str(idx) + '. [' + nbr + '] ' + name + ' · ' + st

async def main(args):
    p = args.params
    offers = _as_list(p.get('offers'))
    offers = _merge_roster(offers, p.get('roster') or '')
    blocks = []
    scene_total = 0
    offer_name = ''
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = o.get('offer_seq', i)
        name = str(o.get('name') or o.get('offer_name') or '').strip()
        if not offer_name and name:
            offer_name = name
        oid = o.get('offer_id') or o.get('offerId') or '—'
        gid = o.get('globalId') or o.get('global_id') or '—'
        st = str(o.get('status') or o.get('result') or 'SUCCESS').upper()
        st_cn = _STATUS_CN.get(st, st)
        title = (str(seq) + '. ' + name) if name else ('商品' + str(seq))
        head = ('  ' + title + '  offer_id=' + str(oid)
                + ' 测试流水号=' + str(gid) + ' 发起状态=' + st_cn)
        scenes = _as_list(o.get('testScenes') or o.get('test_scenes'))
        scenes = sorted(scenes, key=lambda s: (s.get('sort') if isinstance(s, dict) and s.get('sort') is not None else 999))
        scene_total += len(scenes)
        if scenes:
            head += ' 场景数=' + str(len(scenes))
            body = '\n'.join(_scene_line(s, k) for k, s in enumerate(scenes, start=1))
            blocks.append(head + '\n' + body)
        else:
            blocks.append(head + '\n    - （无场景清单）')
    offers_text = '\n'.join(blocks) if blocks else '  （无逐品明细）'
    ret: Output = {
        'offers_text': offers_text,
        'offer_count': str(len([o for o in offers if isinstance(o, dict)])),
        'scene_count': str(scene_total),
        'offer_name': offer_name
    }
    return ret

